namespace Atheriz.Core.Plugins;

// Engine-server build helper shared by the CLI (reset/restart), the in-game
// commands, and the per-game build scripts. The staleness rule here must stay
// identical to the one in build.sh/build.cmd/build.ps1 (generated by
// GameTemplateGenerator): the server Release dll is stale when it is missing
// or any engine source is newer than it, ignoring build outputs. A stale
// server runs an older Atheriz.Core than a freshly built game plugin, and the
// loader unifies engine assemblies by exact version — so the game boots
// engine-only.
public static class EngineBuilder
{
    // Relative layout of the engine checkout. These segments mirror the
    // per-game scripts exactly; changing them breaks every generated build.
    internal const string ServerCsprojRel = "src/Atheriz.Server/Atheriz.Server.csproj";
    internal const string ServerDllRel = "src/Atheriz.Server/bin/Release/net10.0/Atheriz.Server.dll";
    internal const string SrcDirRel = "src";

    // Root-level files whose change invalidates the server dll. The scripts
    // check the same set (build.cmd globs *.props; the names below are the
    // only props files plus the SDK pin, so the sets agree).
    private static readonly string[] WatchedRootFiles =
    [
        "Directory.Build.props",
        "Directory.Packages.props",
        "global.json",
    ];

    /// <summary>
    /// Outcome of an engine build check. <c>Ok</c> false means the build was
    /// attempted and failed — the caller must abort loudly and leave live
    /// state untouched. A skip (fresh tree or unknown checkout) is
    /// <c>Ok</c> true with <c>WasBuilt</c> false.
    /// </summary>
    public sealed record EngineBuildResult(bool Ok, bool WasBuilt, string Message);

    /// <summary>
    /// Locates the engine checkout: <c>ATHERIZ_ROOT</c> wins, then an upward
    /// search from the current directory, then from the running assembly.
    /// An explicitly set <c>ATHERIZ_ROOT</c> is returned verbatim (even when
    /// its project file is missing) so the caller can warn exactly like the
    /// scripts do instead of silently searching elsewhere.
    /// </summary>
    public static bool TryResolveEngineRoot(out string? root)
    {
        root = null;
        try
        {
            var env = Environment.GetEnvironmentVariable("ATHERIZ_ROOT");
            if (!string.IsNullOrWhiteSpace(env))
            {
                try { root = Path.GetFullPath(env); }
                catch { root = env; }
                return true;
            }
            try
            {
                var found = WalkUpForEngine(Directory.GetCurrentDirectory());
                if (found is not null) { root = found; return true; }
            }
            catch { }
            try
            {
                var found = WalkUpForEngine(AppContext.BaseDirectory);
                if (found is not null) { root = found; return true; }
            }
            catch { }
        }
        catch { }
        return false;
    }

    internal static string? WalkUpForEngine(string start)
    {
        var dir = start;
        for (var depth = 0; depth < 12 && !string.IsNullOrEmpty(dir); depth++)
        {
            try
            {
                if (File.Exists(Path.Combine(dir, ServerCsprojRel))) return dir;
            }
            catch { }
            string? parent;
            try { parent = Path.GetDirectoryName(dir); }
            catch { break; }
            if (string.IsNullOrEmpty(parent) || parent == dir) break;
            dir = parent;
        }
        return null;
    }

    /// <summary>
    /// True when the server Release dll is missing or older than the engine
    /// sources. False when the project file itself is missing: with no
    /// sources there is nothing to compare, so the caller warns and skips
    /// (the scripts' WARNING path) instead of treating it as stale.
    /// </summary>
    public static bool EngineNeedsBuild(string engineRoot, out string reason)
    {
        ArgumentException.ThrowIfNullOrEmpty(engineRoot);
        reason = "";
        var csproj = Path.Combine(engineRoot, ServerCsprojRel);
        var dll = Path.Combine(engineRoot, ServerDllRel);
        try
        {
            if (!File.Exists(dll)) { reason = "no built server dll"; return true; }
            if (!File.Exists(csproj)) return false;
            var dllTime = File.GetLastWriteTimeUtc(dll);
            if (File.GetLastWriteTimeUtc(csproj) > dllTime)
            {
                reason = $"{ServerCsprojRel} is newer than the server dll";
                return true;
            }
            foreach (var name in WatchedRootFiles)
            {
                var watched = Path.Combine(engineRoot, name);
                if (File.Exists(watched) && File.GetLastWriteTimeUtc(watched) > dllTime)
                {
                    reason = $"{name} is newer than the server dll";
                    return true;
                }
            }
            var srcRoot = Path.Combine(engineRoot, SrcDirRel);
            if (!Directory.Exists(srcRoot)) return false;
            foreach (var file in Directory.EnumerateFiles(srcRoot, "*.*", SearchOption.AllDirectories))
            {
                var ext = Path.GetExtension(file);
                if (!ext.Equals(".cs", StringComparison.OrdinalIgnoreCase)
                    && !ext.Equals(".csproj", StringComparison.OrdinalIgnoreCase))
                    continue;
                if (IsBuildOutputPath(srcRoot, file)) continue;
                if (File.GetLastWriteTimeUtc(file) > dllTime)
                {
                    reason = $"{Path.GetRelativePath(engineRoot, file)} is newer than the server dll";
                    return true;
                }
            }
        }
        catch { }
        return false;
    }

    // Build-output segments never count as sources (same prune as the
    // scripts' `find ... -name bin -o -name obj -prune`).
    internal static bool IsBuildOutputPath(string srcRoot, string file)
    {
        string rel;
        try { rel = Path.GetRelativePath(srcRoot, file); }
        catch { return false; }
        return rel.Split([Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar])
            .Any(s => s.Equals("bin", StringComparison.OrdinalIgnoreCase)
                || s.Equals("obj", StringComparison.OrdinalIgnoreCase));
    }

    /// <summary>
    /// Rebuilds the engine server (Release) when stale. Never throws for
    /// missing checkouts or failed builds: both come back as results so the
    /// caller can fail loudly without touching live state.
    /// </summary>
    public static async Task<EngineBuildResult> EnsureEngineBuiltAsync(
        string? engineRoot = null,
        Func<string, CancellationToken, Task<bool>>? buildAsync = null,
        CancellationToken cancellationToken = default)
    {
        string? root = engineRoot;
        if (string.IsNullOrWhiteSpace(root) && !TryResolveEngineRoot(out root))
            return new EngineBuildResult(true, false, "Engine checkout not found; skipping server build.");
        var csproj = Path.Combine(root!, ServerCsprojRel);
        if (!File.Exists(csproj))
            return new EngineBuildResult(true, false, $"WARNING: engine sources not found ({csproj}) - skipping server build.");
        if (!EngineNeedsBuild(root!, out _))
            return new EngineBuildResult(true, false, "Engine server is up to date - skipping.");
        Console.Error.WriteLine("Engine server is stale - rebuilding...");
        bool ok;
        try { ok = await (buildAsync ?? ((csproj, ct) => PluginBuilder.BuildAsync(csproj, ct)))(csproj, cancellationToken).ConfigureAwait(false); }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Engine server build threw: {ex.Message}");
            return new EngineBuildResult(false, false, $"Engine server build threw: {ex.Message}");
        }
        if (!ok) return new EngineBuildResult(false, false, "Engine server build failed.");
        return new EngineBuildResult(true, true, "Engine server rebuilt.");
    }
}
